```ts
export function niceTicks(lo: number, hi: number): number[] {
  let min = Math.min(lo, hi, 0), max = Math.max(lo, hi, 0);
  const span = max - min;
  if (!(span > 0)) return [0];
  const raw = span / 4;
  const mag = 10 ** Math.floor(Math.log10(raw));
  const step = [1,2,5,10].map(m=>m*mag).find(s=>s>=raw) ?? 10*mag;
```
