const pctPoint = (v: number) => Math.round(v * 1e4) / 100;

/** Carry a missing point forward (the first value is 0 when the series starts empty). */
function carry(xs: (number | null)[] | undefined, n: number): number[] {
	const out: number[] = [];
	let last = 0;
	for (let i = 0; i < n; i++) {
		const v = xs?.[i];
		if (v != null && Number.isFinite(v)) last = v;
		out.push(last);
	}
	return out;
}

/** Chart-ready curve (percent), or null when there is nothing to draw. */
export function curveView(trial: ScreenTrial | null | undefined): CurveView | null {
	const c = trial?.curve;
	if (!c || !c.t || c.t.length < 2) return null;
	const rule = carry(c.rule, c.t.length).map(pctPoint);
	const hold = carry(c.hold, c.t.length).map(pctPoint);
	const lo = Math.min(...rule, ...hold);
	const hi = Math.max(...rule, ...hold);
	return { t: c.t, labels: c.t.map(dateLabel), rule, hold, ticks: niceTicks(lo, hi) };
}

export interface RuleTile {
	id: string;
	group: "entry" | "fill" | "exit";
	name: string;
	label: string;
	tip: string;
}

const bp = (v: number) => Math.round(v * 1e4);

/** The trading rule of a trial as tiles: entry sign, indicator, regime gate, cost and holding. */
export function screenRule(doc: ScreenDoc, feature: ScreenFeature, trial: ScreenTrial): RuleTile[] {
	const fixed = doc.fixed_sign != null;
	const sign = fixed ? doc.fixed_sign! : trial.train_sign;
	const long = sign >= 0;
	const signs = [...new Set(trial.folds.map((x) => x.train_sign))];
	const changed = signs.length > 1;
	const side = long ? "사고" : "팔";
	const dirTip = fixed
		? `지표가 기준(0)보다 위면 ${side}, 아래면 반대쪽이다. 학습 구간 부호를 +1로 고정했다(fixed_sign ${sign}).`
		: changed
			? `지표가 기준(0)보다 위면 ${side}. 폴드마다 학습 부호가 달라(${signs.map((s) => `${s > 0 ? "+" : "−"}1`).join(" → ")}) 해석에 주의한다.`
			: `지표가 기준(0)보다 위면 ${side}. 학습 구간 부호 ${sign > 0 ? "+1" : "−1"}을 그대로 쓴다.`;
	const tiles: RuleTile[] = [
		{
			id: "direction",
			group: "entry",
			name: long ? "기준 위면 롱" : "기준 위면 숏",
			label: changed ? "부호 바뀜" : long ? "순방향" : "역추세",
			tip: dirTip,
		},
		{
			id: "indicator",
			group: "entry",
			name: featureName(feature),
			label: feature.tradeable === false ? "참고 지표" : (FAMILY_LABEL[feature.family] ?? feature.family),
			tip: feature.tradeable === false
				? `지표는 ${featureDef(feature) || feature.feature}. 체결이 실시간 공개되지 않아 매매에 쓰지 않고 참고 행으로만 둔다.`
				: `지표는 ${featureDef(feature) || feature.feature}.`,
		},
	];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			name: "200일 평균 아래만",
			label: "하락장 게이트",
			tip: "종가가 200일 평균 아래인 날만 점수를 매기고 매매한다.",
		});
	}
	tiles.push(
		{
			id: "fill",
			group: "fill",
			name: `편도 ${bp(doc.cost_per_side)}bp`,
			label: "비용",
			tip: `편도 ${bp(doc.cost_per_side)}bp(보수적 2배)를 매 진입과 청산에 뺀다.`,
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: "청산",
			tip: `진입 뒤 ${trial.h}${doc.unit === "H" ? "시간" : "일"}이 지나면 청산한다.`,
		},
	);
	return tiles;
}

